  var globalAmbient = vec3(SCENE_INFOS.AMBIENT_COLOR_R, SCENE_INFOS.AMBIENT_COLOR_G, SCENE_INFOS.AMBIENT_COLOR_B);
  var isMaterialAmbientEmpty = all(MAT_COLORS.AMBIENT <= vec3f(0.0001));
